import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    static abstract class Account {
        protected long balance;
        Account(long balance) { this.balance = balance; }

        public final void withdraw(long cents) {
            long total = cents + fee(cents);
            if (balance - total < -overdraftLimit()) throw new IllegalStateException("insufficient funds");
            balance -= total;
        }
        protected abstract long fee(long cents);
        protected long overdraftLimit() { return 0; }
