        });
        test("savings never goes negative", () -> {
            Account a = new Savings(1000);
            raises(IllegalStateException.class, () -> a.withdraw(1000));
            eq(a.balance(), 1000L);
        });
        test("checking may overdraw up to 100.00 for free", () -> {
            Account a = new Checking(0);
            a.withdraw(10_000);
            eq(a.balance(), -10_000L);
        });
        test("checking refuses one cent past the limit (boundary)", () -> {
            Account a = new Checking(0);
            raises(IllegalStateException.class, () -> a.withdraw(10_001));
            eq(a.balance(), 0L);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
